// The PayPal Server SDK (generated by APIMatic) for the money-moving calls this app adds:
// donation orders through Checkout. Server-side only: it reads the client secret from the
// environment. Invoicing and reporting stay on the plain REST client in lib/paypal.ts, because
// the SDK doesn't cover them.

import { Client, Environment, OrdersController } from '@paypal/paypal-server-sdk';

let client: Client | undefined;

function sdkClient(): Client {
  if (client) return client;
  const { PAYPAL_CLIENT_ID: id, PAYPAL_SECRET: secret } = process.env;
  if (!id || !secret) throw new Error('PAYPAL_CLIENT_ID and PAYPAL_SECRET must be set (see .env.local)');
  client = new Client({
    clientCredentialsAuthCredentials: { oAuthClientId: id, oAuthClientSecret: secret },
    environment: Environment.Sandbox,
    timeout: 15_000,
  });
  return client;
}

export const ordersApi = () => new OrdersController(sdkClient());
